import{_ as n,o as t,c as e,al as s}from"./chunks/framework.Bm7de0lE.js";const u=JSON.parse('{"title":"XiHan.UI 视图组件","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md","lastUpdated":1786417373000}'),r={name:"introduction.md"};function i(o,a,p,l,d,c){return t(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="xihan-ui-视图组件" tabindex="-1">XiHan.UI 视图组件 <a class="header-anchor" href="#xihan-ui-视图组件" aria-label="Permalink to &quot;XiHan.UI 视图组件&quot;">​</a></h1><p>XiHan.UI 是一套<strong>框架无关</strong>的组件库：状态机与无障碍逻辑沉在无头内核里，每个前端框架只得到一层薄适配器。</p><p>当前提供 <strong>102 个组件</strong>，每个组件同时产出四份东西——无头内核、Vue 组件、自定义元素、默认皮肤。四份同源，行为由内核唯一定义，适配器不重新实现任何逻辑。</p><div class="warning custom-block"><p class="custom-block-title">实验阶段</p><p>XiHan.UI 已发布到 npm，当前版本 <code>1.0.0-alpha.0</code>——这是预发布版本，不承诺语义化版本，接口仍会调整。无障碍扫描已经跑在真实 Chromium 上，首轮扫出的存量问题已经清完，登记表里只剩两条（WC 侧 steps 的必需子节点、breadcrumb 的步骤重放豁免）。<strong>请勿在生产环境依赖。</strong></p></div><h2 id="它和常见组件库有什么不一样" tabindex="-1">它和常见组件库有什么不一样 <a class="header-anchor" href="#它和常见组件库有什么不一样" aria-label="Permalink to &quot;它和常见组件库有什么不一样&quot;">​</a></h2><p>大多数组件库把「行为」和「某个框架的组件模型」焊在一起：换框架就得整套重写，而无障碍与键盘交互是最容易在重写中丢掉的部分。XiHan.UI 把这层拆开：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌──────────────┐  ┌──────────────┐</span></span>
<span class="line"><span>   适配器层          │ @xihan-ui/vue │  │ @xihan-ui/web-components │   ← 只做「把属性挂到宿主元素上」</span></span>
<span class="line"><span>                    └───────┬──────┘  └──────┬───────┘</span></span>
<span class="line"><span>                            └────────┬───────┘</span></span>
<span class="line"><span>                    ┌────────────────▼────────────────┐</span></span>
<span class="line"><span>   无头内核          │       @xihan-ui/headless        │   ← 解剖 + 状态机 + connect</span></span>
<span class="line"><span>                    └────────────────┬────────────────┘</span></span>
<span class="line"><span>              ┌──────────────┬───────┴───────┬──────────────┐</span></span>
<span class="line"><span>   原语层      │ kernel       │ machine       │ behavior     │ position</span></span>
<span class="line"><span>              └──────────────┴───────────────┴──────────────┘</span></span>
<span class="line"><span>                    ┌────────────────────────────────┐</span></span>
<span class="line"><span>   表现层            │ @xihan-ui/tokens  ·  styles     │   ← 令牌与皮肤，纯 CSS，与 JS 无关</span></span>
<span class="line"><span>                    └────────────────────────────────┘</span></span></code></pre></div><p>由此带来四条可以直接兑现的性质：</p><ul><li><strong>同一份行为，两套宿主。</strong> Vue 组件与自定义元素跑的是同一个状态机、同一份 <code>connect</code>。两个 playground 覆盖同一批组件，可以逐帧对照。</li><li><strong>样式与逻辑解耦。</strong> 皮肤只认 <code>data-scope</code> / <code>data-part</code> / <code>data-*</code> 状态属性，不认框架，也不认类名。整包换皮肤不用碰一行 JS。</li><li><strong>无障碍是判据，不是口号。</strong> 每个组件都有一份机读的<strong>键盘规格表</strong>（共 375 条），它同时是测试的分母：用例少覆盖一条即判套件失败。</li><li><strong>依赖面收得很紧。</strong> 全部库包的运行时第三方依赖只有一个（<code>@internationalized/date</code>，仅日期族使用）。定位、代码着色、Web Components 响应式基类都是自研。</li></ul><h2 id="从哪儿开始" tabindex="-1">从哪儿开始 <a class="header-anchor" href="#从哪儿开始" aria-label="Permalink to &quot;从哪儿开始&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你想做的事</th><th>去这里</th></tr></thead><tbody><tr><td>先看清楚整体是怎么搭的</td><td><a href="./overview">架构总览</a></td></tr><tr><td>把它接进现有项目</td><td><a href="./installation">安装与接入</a></td></tr><tr><td>写出第一个能跑的组件</td><td><a href="./quickstart">快速上手</a></td></tr><tr><td>查某个组件有哪些部件、支持哪些按键</td><td><a href="./components/">组件总览</a></td></tr><tr><td>改主题、改皮肤</td><td><a href="./guide/theme">设计令牌与主题</a>、<a href="./guide/styling">皮肤与样式分层</a></td></tr><tr><td>用 Vue / 用原生自定义元素</td><td><a href="./adapters/vue">Vue 适配器</a>、<a href="./adapters/web-components">Web Components 适配器</a></td></tr><tr><td>做 AI 对话界面</td><td><a href="./guide/ai">AI 协议内核</a></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>源码仓库：<a href="https://github.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://gitee.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">Gitee</a> · <a href="https://gitcode.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">GitCode</a></li><li>同生态的另外两个仓库：<a href="https://framework.docs.xihanfun.com/" target="_blank" rel="noreferrer">XiHan.Framework 开发框架</a>、<a href="https://basicapp.docs.xihanfun.com/" target="_blank" rel="noreferrer">XiHan.BasicApp 基础应用</a></li></ul><div class="tip custom-block"><p class="custom-block-title">与 XiHan.BasicApp 的关系</p><p>XiHan.BasicApp 的前端目前<strong>不使用</strong> XiHan.UI，它基于 Naive UI 构建。两者是独立演进的两条线，BasicApp 的前端约定请看<a href="https://basicapp.docs.xihanfun.com/frontend/introduction" target="_blank" rel="noreferrer">基础应用前端手册</a>。</p></div>`,14)])])}const g=n(r,[["render",i]]);export{u as __pageData,g as default};
